style.css:
@-moz-document domain("instagram.com") {
:root {
  --accent: #9cad87 !important;
  --primary-button-background: #9cad87 !important;
  --primary-button-text: #fffaf0 !important;

  --ig-outgoing-message-bubble: 156,173,135 !important;

  --web-wash: #eee7d6 !important;
  --wash: #eee7d6 !important;
  --surface-background: #f8f3e6 !important;
  --card-background: #f8f3e6 !important;
  --popover-background: #f8f3e6 !important;
  --messenger-card-background: #f8f3e6 !important;
  --mwp-message-row-background: #f8f3e6 !important;
  --nav-bar-background: #dfe5c9 !important;

  --primary-text: #3f4d38 !important;
  --secondary-text: #5f7155 !important;
  --primary-icon: #5f7155 !important;
  --secondary-icon: #7f936c !important;

  --divider: #c6d0b8 !important;
  --scroll-thumb: #9cad87 !important;

  --chat-incoming-message-bubble-background-color: #e2e8cf !important;
  --chat-outgoing-message-bubble-background-color: #9cad87 !important;
  --comment-background: #e2e8cf !important;
  --input-background: #fffaf0 !important;
  --text-input-bar-background: #fffaf0 !important;
}

/* Fondo general */
html,
body,
main,
section,
header,
nav,
aside,
article,
div[role="dialog"] {
  background-color: #eee7d6 !important;
  color: #3f4d38 !important;
}

html,
body {
    background-color: #eee7d6 !important;
}

/* Tarjetas y contenedores */
section,
article,
div[role="dialog"] {
    background-color: rgba(248,243,230,.92) !important;
    backdrop-filter: blur(6px);
    border: 1px solid #c6d0b8 !important;
    border-radius: 18px !important;
}

/* Sidebar */
nav,
div[role="navigation"] {
    background-color: #dfe5c9 !important;
}

/* Texto general con mejor contraste */
span,
p,
a,
h1,
h2,
h3,
h4,
label {
  color: #3f4d38 !important;
}

/* Texto secundario */
time,
small {
  color: #5f7155 !important;
}

/* Burbujas enviadas */
.x5slmwz {
  background-color: #9cad87 !important;
}

/* Texto dentro de burbujas enviadas */
.x5slmwz,
.x5slmwz * {
  color: #fffaf0 !important;
}

/* Burbujas recibidas */
div[style*="--chat-incoming-message-bubble-background-color"],
[style*="chat-incoming"] {
  background-color: #e2e8cf !important;
  color: #3f4d38 !important;
}

/* Inputs */
input,
textarea,
[contenteditable="true"] {
  background-color: #fffaf0 !important;
  color: #3f4d38 !important;
  border-color: #c6d0b8 !important;
}

/* Botones */
button {
  color: #3f4d38 !important;
}

/* Botones principales */
button[type="submit"],
div[role="button"] {
  border-radius: 14px !important;
}

/* Iconos */
svg {
  color: #5f7155 !important;
  fill: #5f7155 !important;
}

/* Scroll */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #eee7d6;
}

::-webkit-scrollbar-thumb {
  background: #9cad87;
  border-radius: 20px;
}
}
